import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel source for batched matrix multiplication (C = A @ B)
batched_matmul_kernel_source = """
__global__ void batched_matmul_kernel(const float* A, const float* B, float* C, int batch_size, int m, int k, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * m * n) {
        int b = idx / (m * n);
        int rem = idx % (m * n);
        int i = rem / n;
        int j = rem % n;
        float sum = 0.0f;
        for (int l = 0; l < k; ++l) {
            const float a_val = A[(b * m + i) * k + l];
            const float b_val = B[(b * k + l) * n + j];
            sum += a_val * b_val;
        }
        C[idx] = sum;
    }
}

torch::Tensor batched_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int batch_size = A.size(0);
    int m = A.size(1);
    int k = A.size(2);
    int n = B.size(2);

    auto size = A.numel();
    auto out = torch::zeros(batch_size, m, n, device=A.device(), dtype=A.dtype());

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    batched_matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float()>, B.data_ptr<float()>, out.data_ptr<float()>, batch_size, m, k, n);

    return out;
}
"""

# C++ source for the function signature
batched_matmul_cpp_source = (
    "torch::Tensor batched_matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code for batched matmul
batched_matmul = load_inline(
    name="batched_matmul",
    cpp_sources=batched_matmul_cpp_source,
    cuda_sources=batched_matmul_kernel_source,
    functions=["batched_matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.batched_matmul = batched_matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.batched_matmul.batched_matmul_cuda(A, B)
